-- 170_school_intro_backfill_round3.sql
-- 院校简介回填（第 170 批，2026-11-24）：第三批 6 所「官网可查、简介为空」院校。
--
-- 口径同 168/169：只用院校官网自述页原文，逐字摘录，200-500 字，句末截断；
-- 仅当 intro 为空时更新，重复执行不覆盖既有简介；不物理删除。
-- 证据：backfill_local/out/school_intro_170_evidence.csv
--
-- 本批方法变化：本地直连被 WAF 拦截（返回 400/412/403），改由生产服务器出口抓取；
-- 591/641 首页为 JS 壳或跳转，按站内导航定位到「校情概览/学校简介」正文页；
-- 715/722/1003/1006 从栏目列表页进入正文页抓取，避免列表摘要的「…」截断。
--
-- 仍未处理（下轮候选，原因）：
--   #25/#26/#202/#264/#536 机械总院各所：官网统一跳转集团站，无各所独立简介，不混用；
--   #30/#183 中国北方车辆研究所/内蒙古金属材料研究所：站内仅新闻流，无简介页；
--   #163 山西大同大学：云端返回 403「请添加路由白名单」；#834 北京警察学院：503；
--   #653/#711/#789/#1035/#1039：简介页 412（JS/WAF 挑战，需浏览器执行脚本）；
--   #830/#844/#926/#902/#831：#830/#844 无简介入口；#926 仅新闻流；#902 概况页未开放；
--     #831 学校简介为跳转壳（webterren 统计脚本），未取到正文；
--   #842/#1062：简介页 404 或仅导航壳；#780/#897/#988/#1034/#1065：官网当前不可达。

UPDATE kaoyan_schools AS s
SET intro = v.intro,
    updated_at = now()
FROM (VALUES
    (591, '汕头大学是1981年经国务院批准成立的广东省省属综合性大学，是教育部、广东省、李嘉诚基金会三方共建的高等院校，全国首批高等教育综合改革试点高校，广东省高水平大学重点学科建设高校，广东省首家高等教育体制机制改革实验示范校，广东省深化新时代教育评价改革试点高校，广东省"党建工作示范高校"培育创建单位，也是全球唯一一所由私人基金会李嘉诚基金会持续资助的公立大学。学校设有文学院、理学院、工学院、法学院、商学院、长江艺术与设计学院、长江新闻与传播学院、医学院、化学化工学院（碳中和未来技术学院）、数学与计算机学院、国际学院、马克思主义学院、继续教育学院等13个学院，面向全国（含港澳台地区）招收博士、硕士和本科生，并设研究生院和12个住宿学院（书院）。现有专任教师1400多人，全日制在校生近2.4万人，已为社会培养出各类人才逾18万人。'),
    (641, '海南医科大学作为海南自由贸易港内唯一一所公办本科医学院校，既承担着高等教育强港的重要使命，也承载着建设“更高水平健康岛”的重要基础支撑。更好地服务于自贸港建设，服务于海洋强国、南海安全等国家战略，充分发挥海南地缘、资源和政策优势，助力“健康海南”和“健康中国”建设，加快发展热带医学，服务“一带一路”尤其是东南亚人类健康命运共同体建设，海南医科大学重任在肩，责无旁贷。海南医科大学坐落在素有“椰城”之称的热带滨海城市—海南省省会海口市。其前身始于创立于1947年的私立海强医事技术（职业）学校和创立于1948年的私立海南大学医学院。现有城西（主校区）、桂林洋（新校区）和龙华等三个校区，占地1416.71亩。'),
    (715, '云南中医药大学是云南省政府与国家中医药管理局共建高校，是最早开展民族医药人才培养的高校，是首开中医药高等教育海外办学先河的高校，也是云南省唯一的中医药本科院校。云南中医药大学前身为云南中医学院，始建于1960年。1960年5月，云南中医学院在云南省中医学校的基础上创立，是全国第二批高等中医药本科院校，吴佩衡被任命为首任院长。1960年9月1日，云南省中医医院划归作为学校附属医院。1981年成为首批获得学士学位授予权的高等学校，1986年获硕士学位授予权，2000年获得招收学历教育外国留学生资格，2016年成为云南省人民政府与国家中医药管理局共建高校，2018年成为博士学位授予单位，同年更名为云南中医药大学，2025年获批推荐优秀应届本科毕业生免试攻读研究生资格。目前已发展成为以中医药为主体、民族医药、国际化教育为特色，以本科教育为基础，研究生教育规模不断扩大，继续教育呈现良好态势，医、理、工、管多学科协调发展的综合性中医药院校。'),
    (722, '玉溪师范学院是省属全日制普通本科院校，1978年经云南省批准成立玉溪师范专科班。1983年经云南省人民政府批准，改建为玉溪师范专科学校。1992年经原国家教育委员会批准，更名为玉溪师范高等专科学校。2000年经教育部批准，成立玉溪师范学院。2024年获批硕士学位授予单位。学校坐落于滇中名城“高原水乡”“中国十佳休闲宜居生态城市”、聂耳故乡——玉溪市，占地面积1014.45亩，是距离省会昆明最近的地方院校。学校现有内设党政管理机构13个，教学科研类机构19个，服务保障类机构16个，其他机构6个，云南省监委派驻机构1个。全日制在校学生数为14214人，教职工数为946人。学校秉承“至真至善 致美致用”校训精神，立足滇中、扎根玉溪、服务云南、辐射东南亚，为云南尤其是玉溪和周边地区培养近8万余名服务地方基础教育和经济社会发展需要的合格人才，为区域基础教育和滇中经济社会发展做出贡献。'),
    (1003, '湖南警察学院是湖南省唯一一所全日制公安类普通本科高等院校。学校始创于1949年，2010年经教育部批准升格为本科院校，2014年获批学士学位授予权，2021年获批湖南省硕士学位授予单位立项建设。建校77年来，累计为全省乃至全国公安政法系统输送8万余名高素质警务人才，素有“三湘警察摇篮”之美誉。近年来，学校聚焦“全国一流、中部领先”的现代化公安院校创建目标，加快推进“一二三四五”高质量发展战略，即紧紧围绕“申硕强本创一流”一条主线，做大做强公安学、公安技术两大主干优势学科，实施教学科研水平提升、学生管理能力提升、服务实战质效提升三大工程，强化师资、设施、安全、治理四项基础保障，狠抓全面从严管党治警五项举措落实，着力推动综合实力争先进位，全力服务湖南公安工作现代化，为加快实现“三高四新”美好蓝图贡献公安教育力量。学校坐落于长沙经济技术开发区，办学区位优越、校园环境雅致。校园占地面积近700亩，校舍总建筑面积24.73万平方米；教学科研仪器设备总值1.3亿元，馆藏纸质图书104.85万册、电子图书46.1万册。校内建成标准化实验实训场所96个，校外稳固共建教学实习基地98个。'),
    (1006, '长沙工业学院是教育部批准设立的应用型公办普通本科院校，2024年5月由湖南师范大学树达学院转设而成。学院实行由省人民政府与长沙市人民政府共管，以长沙市人民政府为主管理的体制，省教育厅归口管理学校的教育业务。学院校园总体规划近2000亩，分三期建成，一期占地670亩，已完成21万多平方米的校舍建筑建设。学院紧盯湖南“4×4”和长沙“4433”现代化产业体系发展战略和产业需求，服务长沙全球研发中心城市建设，构建了以新工科为主导，多学科交叉融合、协调发展的高水平学科专业体系，开设的机械设计制造及其自动化、人工智能等22个专业均紧密对接长沙市11条新兴及优势产业链。学院依托长沙国家级智能制造示范区产业集聚优势，与长沙经济技术开发区、望城经济技术开发区、宁乡经济技术开发区、马栏山（长沙）视频文创园等4个国家级园区，以及三一重工、山河智能、蓝思科技、树根互联等31家企业建立了紧密合作关系，搭建了“政、园、企、校”协同育人平台。')
) AS v(id, intro)
WHERE s.id = v.id
  AND (s.intro IS NULL OR btrim(s.intro) = '');
